var W4_GENESIS = "";
var MemoryStorage = class {
  map = /* @__PURE__ */ new Map();
  getItem(k) {
    return this.map.get(k) ?? null;
  }
  setItem(k, v) {
    this.map.set(k, v);
  }
  removeItem(k) {
    this.map.delete(k);
  }
};
test("the Build catalogue: every definition is complete and consistent; early buildings are open, later ones locked and say why", () => {
  const ids = /* @__PURE__ */ new Set();
  for (const d of BUILD_CATALOGUE) {
    assert2.ok(!ids.has(d.id) && /^[a-z_]+$/.test(d.id), `stable unique id ${d.id}`);
    ids.add(d.id);
    assert2.ok(BUILD_CATEGORIES.includes(d.category), d.id);
    assert2.ok(d.footprint.w >= 1 && d.footprint.d >= 1 && Number.isInteger(d.footprint.w) && Number.isInteger(d.footprint.d), d.id);
    assert2.ok(d.placement.maxStep >= 1 && d.placement.gap >= 0, d.id);
    assert2.ok(d.stages.length >= 1 && d.stages.every((s2) => s2.work >= 1 && s2.label), d.id);
    const sum2 = {};
    for (const s2 of d.stages) for (const [k, n] of Object.entries(s2.materials)) sum2[k] = (sum2[k] ?? 0) + n;
    assert2.deepEqual(Object.keys(d.materials).sort(), Object.keys(sum2).sort());
    for (const k of Object.keys(sum2)) assert2.equal(d.materials[k], sum2[k], `${d.id} ${k}`);
    assert2.equal(d.work, d.stages.reduce((a, s2) => a + s2.work, 0));
    assert2.ok(d.function.summary.length > 10, d.id);
    assert2.ok(d.model.id && d.model.stages.length === d.stages.length && d.model.asset.startsWith("render/"), d.id);
    for (const b of d.solids) assert2.ok(b.x0 >= 0 && b.z0 >= 0 && b.x1 <= d.footprint.w && b.z1 <= d.footprint.d && b.h > 0, `${d.id} solid inside footprint`);
    for (const p of d.prerequisites.buildings) assert2.ok(buildingDef(p), `${d.id} prerequisite ${p}`);
  }
  for (const id2 of ["lean_to", "campfire", "workbench", "log_store"]) {
    const d = buildingDef(id2);
    assert2.equal(d.tier, "early");
    assert2.ok(d.implemented);
    assert2.deepEqual(d.prerequisites, { buildings: [], tools: [] });
    assert2.ok(Object.keys(d.materials).every((k) => !FUTURE_MATERIALS[k]), `${id2} needs only W4 materials`);
  }
  assert2.deepEqual(buildingDef("lean_to").materials, { branch: 6, cord: 2, log: 2 });
  assert2.deepEqual(buildingDef("campfire").materials, { branch: 3, stone: 6 });
  assert2.deepEqual(buildingDef("workbench").materials, { log: 3, stone: 2 });
  assert2.deepEqual(buildingDef("log_store").materials, { branch: 4, log: 2, stone: 2 });
  for (const id2 of ["cabin", "timber_house", "stone_house", "storage_shed", "workshop", "forge", "barn", "farm_plot", "water_well", "rain_barrel", "fence", "gate", "bridge"]) {
    assert2.ok(buildingDef(id2), id2);
    assert2.equal(buildingDef(id2).tier, "later");
  }
  const s = GameSession.genesis(1337, GENERATOR_V2, "wilderness");
  for (const d of BUILD_CATALOGUE) {
    const why = lockReasons(s.world, d);
    assert2.equal(why.length === 0, d.tier === "early", `${d.id}: ${why.join("; ")}`);
  }
  assert2.match(lockReasons(s.world, buildingDef("stone_house")).join(";"), /cut stone .*W6/);
  assert2.match(lockReasons(s.world, buildingDef("storage_shed")).join(";"), /finished workbench.*hammer/);
  assert2.deepEqual(WILD_RECIPES.filter((r) => r.station === "workbench").map((r) => r.id).sort(), ["hammer", "knife", "planks", "stone_pickaxe", "wooden_chest"]);
});
