  const c = siteCellsOf(site);
  const box = solidRect(site, buildingDef("workbench").solids[0]);
  assert2.deepEqual([box.x0, box.z0, box.x1, box.z1], [c.x0, c.z0, c.x1, c.z1]);
  const cx = (c.x0 + c.x1) / 2, cz = (c.z0 + c.z1) / 2;
